"""The multi-symbol replay session: orchestration only.

:class:`EventReplayer` owns the session state (per-symbol books, sequence
counters, the global idempotency log, the matching configuration) and the
per-event pipeline: envelope validation, payload normalization, structural
validation, global idempotency, per-symbol sequencing and the single
deterministic commit. Everything type-specific — schemas, inline key sets,
business handlers, price-limit pre-checks — comes from the event-kind
registry, so this module never switches on an event type itself.
"""

from __future__ import annotations

from ..engine import DUPLICATE_EVENT_ID
from .constants import (
    DEFAULT_CONFIG,
    DUPLICATE,
    EVENT_ID_CONFLICT,
    INVALID_EVENT,
    OUT_OF_ORDER,
    REJECTED,
    SEQUENCE_GAP,
    SUPPORTED_TYPES,
    _ENVELOPE_KEYS,
)
from .handlers import price_limit_rejection
from .registry import KINDS, kind_for
from .serialization import _digest, canonical_json
from .state import (
    _Applied,
    _CommitContext,
    _SymbolState,
    invalid_result,
)
from .validation import _validate_config, _valid_timestamp


class EventReplayer:
    """Stateful, resumable multi-symbol replay session.

    One session binds together the per-symbol books, per-symbol sequence
    counters, the global idempotency log and the matching configuration.
    Instances are normally obtained from :func:`replay_events` or restored via
    :func:`restore_replayer`; they are not thread safe on purpose.
    """

    def __init__(self, config: dict[str, object] | None = None) -> None:
        if config is not None and not isinstance(config, dict):
            raise TypeError("config must be a JSON object or None")
        self.config: dict[str, object] = dict(DEFAULT_CONFIG if config is None else config)
        _validate_config(self.config)
        # Static per-security price bounds (closed interval), parsed from the
        # validated config. They seed each security's *active* interval (and
        # a legacy snapshot's restored one); accepted PRICE_LIMIT_UPDATE
        # events then replace the active interval per security. Securities
        # without an entry start unlimited.
        raw_limits = self.config.get("price_limits") or {}
        self.price_limits: dict[str, tuple[int, int]] = {
            symbol: (bounds["lower"], bounds["upper"])
            for symbol, bounds in raw_limits.items()
        }
        self.config_digest = _digest(self.config)
        self._symbols: dict[str, _SymbolState] = {}
        # Global index of every accepted eventId: eventId -> (symbol, content).
        self._events: dict[str, tuple[str, str]] = {}

    # -- book helpers -------------------------------------------------------

    def book(self, symbol: str) -> tuple[list[dict[str, int]], list[dict[str, int]]]:
        """The final ``(bids, asks)`` aggregates for one security."""
        state = self._symbols.get(symbol)
        if state is None:
            return [], []
        return state.engine.snapshot()

    # -- main entry ---------------------------------------------------------

    def submit(self, events: list[dict[str, object]]) -> list[dict[str, object]]:
        """Apply an ordered list of event objects, one result per event."""
        return [self._submit_one(event) for event in events]

    def _submit_one(self, event: object) -> dict[str, object]:
        # ---- envelope validation (nothing is consumed on failure) --------
        if not isinstance(event, dict):
            return invalid_result(event)
        event_id = event.get("event_id")
        symbol = event.get("symbol")
        sequence = event.get("sequence")
        timestamp = event.get("timestamp")
        valid_envelope_ids = (
            isinstance(event_id, str)
            and event_id != ""
            and isinstance(symbol, str)
            and symbol != ""
            and isinstance(sequence, int)
            and not isinstance(sequence, bool)
            and sequence > 0
        )
        if not valid_envelope_ids:
            # The symbol cannot be trusted yet, so no book is echoed and no
            # symbol state is created.
            return invalid_result(event)

        def reject_envelope(code: str = INVALID_EVENT) -> dict[str, object]:
            # A structurally invalid event for a recognizable symbol echoes the
            # untouched book but never mutates or registers anything.
            return invalid_result(event, code, state=self._symbols.get(symbol))

        if "timestamp" in event and not _valid_timestamp(timestamp):
            return reject_envelope()

        # The baseline payload is either nested under "event" or carried
        # inline alongside the envelope fields.
        if "event" in event:
            nested = event["event"]
            envelope_keys = _ENVELOPE_KEYS | {"event"}
            if not isinstance(nested, dict):
                return reject_envelope()
            payload: dict[str, object] = nested
            # The wrapper may only carry envelope fields plus the payload.
            if not set(event) <= envelope_keys:
                return reject_envelope()
        else:
            # The inline form may carry envelope fields plus exactly the fields
            # of its own payload kind.
            inline_kind = kind_for(event.get("type"))
            if inline_kind is None or not set(event) <= (
                _ENVELOPE_KEYS | inline_kind.payload_keys
            ):
                return reject_envelope()
            # Keep event_id/type (payload fields); strip only symbol,
            # sequence and timestamp, which are envelope-only.
            payload = {
                key: value
                for key, value in event.items()
                if key not in ("symbol", "sequence", "timestamp")
            }
        event_type = payload.get("type")
        if not isinstance(event_type, str) or event_type not in SUPPORTED_TYPES:
            return reject_envelope()
        # Validate the full payload schema up front, so malformed content is
        # classified INVALID_EVENT and reaches neither ordering nor the book.
        # The wrapper and the payload must identify the same event.
        if payload.get("event_id") != event_id:
            return reject_envelope()
        kind = KINDS[event_type]
        if kind.schema_error(payload) is not None:
            return reject_envelope()

        # A symbol state is created only once the event is fully well formed;
        # failures that precede dispatch must not register an empty book.
        state = self._symbols.get(symbol)
        known_symbol = state is not None
        if state is None:
            state = _SymbolState()
            # The active interval starts at the static configuration; an
            # accepted PRICE_LIMIT_UPDATE replaces it from then on.
            state.price_limits = self.price_limits.get(symbol)

        # ---- global idempotency (checked before sequencing) --------------
        # A retried delivery carries its original, now-stale sequence; it must
        # still be recognized as a duplicate rather than as out-of-order.
        content = canonical_json(payload).decode("utf-8")
        prior = self._events.get(event_id)
        if prior is not None:
            prior_symbol, prior_content = prior
            if prior_symbol == symbol and prior_content == content:
                bids, asks = state.engine.snapshot()
                return {
                    "event_id": event_id,
                    "symbol": symbol,
                    "sequence": sequence,
                    "status": DUPLICATE,
                    "trades": [],
                    "book_changes": {"bids": [], "asks": []},
                    "bids": bids,
                    "asks": asks,
                }
            # Same id, different symbol or different normalized content: a
            # conflict consumes neither sequence nor book state, so the
            # correct next event can follow immediately.
            return invalid_result(
                event, EVENT_ID_CONFLICT,
                expected_sequence=state.last_sequence + 1 if known_symbol else None,
                state=state if known_symbol else None,
            )

        # ---- per-symbol strict sequence ordering -------------------------
        expected = state.last_sequence + 1
        if sequence < expected or sequence > expected:
            code = OUT_OF_ORDER if sequence < expected else SEQUENCE_GAP
            return invalid_result(
                event, code, expected_sequence=expected,
                state=state if known_symbol else None,
            )

        # ---- committed application ---------------------------------------
        # From here on the event is structurally valid and in sequence: it is
        # a committed application. The context owns the single symbol
        # registration, the deterministic id/sequence commit, the post-event
        # book echo and the response assembly; the registered kind describes
        # everything type-specific.
        ctx = _CommitContext(
            self._symbols, self._events,
            event_id, event_type, symbol, sequence, content, state, known_symbol,
        )
        ctx.register_symbol()

        # A derived child id (``plan_id#slice``) is reserved from plan start;
        # it occupies both the order-id and event-id role of the future child,
        # so no external event — baseline or parent-order command — may reuse
        # it as an event id.
        if event_id in state.plan_index:
            # Committed like every baseline business rejection: the well-formed
            # event occupies its id and the sequence, but nothing else moves.
            return ctx.finish(_Applied(REJECTED, code=DUPLICATE_EVENT_ID))

        # ---- active per-security price limits ---------------------------
        # Enforced after the envelope, idempotency, sequence and identifier
        # conflict checks, and strictly before matching or any state change.
        # The identifier clashes the baseline engine would reach first (a
        # reused order id, a replace against a missing order, a duplicate plan
        # or a clashing derived id) keep their rejection-code precedence; a
        # price breach is only reported when none applies. The interval tested
        # here is the security's *active* one: the static config interval as
        # last replaced by any accepted PRICE_LIMIT_UPDATE.
        if kind.price_limit_checked:
            price_rejection = price_limit_rejection(payload, event_type, state)
            if price_rejection is not None:
                # A committed business rejection: it occupies the event id and
                # advances the symbol sequence, but performs no matching, leaves
                # no order or plan behind and spends no trade id. Baseline event
                # ids also occupy the per-symbol engine journal, exactly as an
                # engine-side business rejection would; plan commands live solely
                # in the replay log.
                return ctx.finish(_Applied(
                    REJECTED, code=price_rejection,
                    occupy_engine_id=not kind.replay_only,
                ))

        # Only book-moving kinds capture the visible levels up front, so the
        # level-diff reports drained levels and iceberg replenishment.
        if kind.captures_book:
            ctx.capture_book()
        return ctx.finish(kind.handler(self, ctx, payload))

def _schema_error(obj: dict[str, object]) -> str | None:
    keys = set(obj)
    event_type = obj.get("type")
    if event_type == EXECUTION_REPORT:
        # A pure query: exactly the four fields, string identifiers and a
        # positive integer benchmark (booleans are not integers).
        if keys != _REPORT_KEYS:
            return INVALID_SCHEMA
        if not isinstance(obj.get("event_id"), str):
            return INVALID_SCHEMA
        if not isinstance(obj.get("order_id"), str):
            return INVALID_SCHEMA
        if not _is_positive_int(obj.get("benchmark_price")):
            return INVALID_SCHEMA
        return None
    if event_type == IMPACT_REPORT:
        # A pure read-only what-if query: exactly the five fields, a string
        # event id, a BUY/SELL side and positive integer quantity and
        # benchmark (booleans are not integers).
        if keys != _IMPACT_KEYS:
            return INVALID_SCHEMA
        if not isinstance(obj.get("event_id"), str):
            return INVALID_SCHEMA
        if obj.get("side") not in (BUY, SELL):
            return INVALID_SCHEMA
        if not _is_positive_int(obj.get("quantity")):
            return INVALID_SCHEMA
        if not _is_positive_int(obj.get("benchmark_price")):
            return INVALID_SCHEMA
        return None
    if event_type == ACCOUNT_REPORT:
        # A pure query: exactly the four fields, non-empty string
        # identifiers and a positive integer mark (booleans are not
        # integers).
        if keys != _ACCOUNT_REPORT_KEYS:
            return INVALID_SCHEMA
        if not _is_non_empty_str(obj.get("event_id")):
            return INVALID_SCHEMA
        if not _is_non_empty_str(obj.get("account_id")):
            return INVALID_SCHEMA
        if not _is_positive_int(obj.get("mark_price")):
            return INVALID_SCHEMA
        return None
    if event_type == DAY_END_RECONCILIATION:
        # A pure read-only query: exactly the four fields, a non-empty
        # string event id and the two external record arrays. Identifiers
        # must be unique within their array and booleans are not integers.
        if keys != _RECONCILIATION_KEYS:
            return INVALID_SCHEMA
        if not _is_non_empty_str(obj.get("event_id")):
            return INVALID_SCHEMA
        expected_trades = obj.get("expected_trades")
        expected_accounts = obj.get("expected_accounts")
        if not isinstance(expected_trades, list):
            return INVALID_SCHEMA
        if not isinstance(expected_accounts, list):
            return INVALID_SCHEMA
        seen_trade_ids: set[int] = set()
        for item in expected_trades:
            if not isinstance(item, dict) or set(item) != _EXPECTED_TRADE_KEYS:
                return INVALID_SCHEMA
            trade_id = item.get("trade_id")
            if not _is_positive_int(trade_id) or trade_id in seen_trade_ids:
                return INVALID_SCHEMA
            seen_trade_ids.add(trade_id)
            if not _is_non_empty_str(item.get("maker_order_id")):
                return INVALID_SCHEMA
            if not _is_non_empty_str(item.get("taker_order_id")):
                return INVALID_SCHEMA
            if not _is_positive_int(item.get("price")):
                return INVALID_SCHEMA
            if not _is_positive_int(item.get("quantity")):
                return INVALID_SCHEMA
        seen_account_ids: set[str] = set()
        for item in expected_accounts:
            if not isinstance(item, dict) or set(item) != _EXPECTED_ACCOUNT_KEYS:
                return INVALID_SCHEMA
            account_id = item.get("account_id")
            if not _is_non_empty_str(account_id) or account_id in seen_account_ids:
                return INVALID_SCHEMA
            seen_account_ids.add(account_id)
            if not _is_int(item.get("net_position")):
                return INVALID_SCHEMA
            if not _is_int(item.get("cash_balance")):
                return INVALID_SCHEMA
        return None
    if not keys <= _ALL_KEYS:
        return INVALID_SCHEMA
    if not isinstance(obj.get("event_id"), str):
        return INVALID_SCHEMA

    if event_type == CANCEL:
        if keys != _CANCEL_KEYS:
            return INVALID_SCHEMA
        if not isinstance(obj.get("order_id"), str):
            return INVALID_SCHEMA
        return None

    if event_type == REPLACE:
        # Side and order type are inherited from the target, so the event
        # must not restate them; time-in-force is always GTC.
        if not keys >= _REQUIRED_REPLACE_KEYS:
            return INVALID_SCHEMA
        if not keys <= _ALLOWED_REPLACE_KEYS:
            return INVALID_SCHEMA
        if not isinstance(obj.get("order_id"), str):
            return INVALID_SCHEMA
        if not _is_positive_int(obj.get("quantity")):
            return INVALID_SCHEMA
        if not _is_positive_int(obj.get("price")):
            return INVALID_SCHEMA
        if "display_quantity" in obj:
            display_quantity = obj["display_quantity"]
            if (
                not _is_positive_int(display_quantity)
                or display_quantity > obj["quantity"]
            ):
                return INVALID_SCHEMA
        return None

    if event_type != ADD:
        return INVALID_SCHEMA
    if not keys >= _REQUIRED_ADD_KEYS:
        return INVALID_SCHEMA

    if not isinstance(obj.get("order_id"), str):
        return INVALID_SCHEMA
    if obj.get("side") not in (BUY, SELL):
        return INVALID_SCHEMA
    order_type = obj.get("order_type")
    if order_type not in (LIMIT, MARKET, ICEBERG):
        return INVALID_SCHEMA
    if not _is_positive_int(obj.get("quantity")):
        return INVALID_SCHEMA
    if "account_id" in obj and not (
        isinstance(obj.get("account_id"), str) and obj["account_id"] != ""
    ):
        # The account tag is optional but may only be a non-empty string.
        return INVALID_SCHEMA
    if order_type != ICEBERG and "display_quantity" in obj:
        # Only iceberg orders carry a display slice size.
        return INVALID_SCHEMA

    if order_type == ICEBERG:
        # Iceberg orders are always-priced GTC limit orders whose single
        # maximum visible slice must not exceed the total quantity.
        if not _is_positive_int(obj.get("price")):
            return INVALID_SCHEMA
        display_quantity = obj.get("display_quantity")
        if not _is_positive_int(display_quantity) or display_quantity > obj["quantity"]:
            return INVALID_SCHEMA
        tif = obj.get("time_in_force")
        if "time_in_force" in obj and tif != GTC:
            # Only an omitted field or explicit GTC are accepted.
            return INVALID_SCHEMA
        return None

    if "price" in obj:
        price = obj["price"]
        if order_type == LIMIT:
            if not _is_positive_int(price):
                return INVALID_SCHEMA
        elif price is not None:
            # MARKET orders must not carry a non-null price.
            return INVALID_SCHEMA
    elif order_type == LIMIT:
        return INVALID_SCHEMA

    if "time_in_force" in obj:
        tif = obj["time_in_force"]
        if tif not in (GTC, IOC, FOK):
            # Non-string values and unknown time-in-force values.
            return INVALID_SCHEMA
        if order_type == MARKET and tif == GTC:
            return INVALID_SCHEMA

    return None

def _books(self, side: str) -> tuple[dict[int, deque[str]], dict[int, int]]:
    """The book and visible totals on which ``side`` rests."""
    if side == BUY:
        return self._bids, self._bid_totals
    return self._asks, self._ask_totals

def _opposite(self, side: str) -> tuple[dict[int, deque[str]], dict[int, int]]:
    """The book and visible totals against which ``side`` matches."""
    if side == BUY:
        return self._asks, self._ask_totals
    return self._bids, self._bid_totals

@staticmethod
def _tradable_fn(side: str, limit: int | None):
    if side == BUY:
        def tradable(price: int) -> bool:
            return limit is None or price <= limit
    else:
        def tradable(price: int) -> bool:
            return limit is None or price >= limit
    return tradable

def _add(
    self, event_id: str, obj: dict[str, object]
) -> tuple[str, str, str | None, list[dict[str, object]], dict[str, object] | None]:
    order_id: str = obj["order_id"]
    if order_id in self._order_ids or order_id in self._reserved_order_ids:
        return event_id, REJECTED, DUPLICATE_ORDER_ID, [], None
    self._order_ids.add(order_id)

    side: str = obj["side"]
    order_type: str = obj["order_type"]
    quantity: int = obj["quantity"]
    remaining: int = quantity
    is_iceberg = order_type == ICEBERG
    limit: int | None = obj["price"] if order_type in (LIMIT, ICEBERG) else None
    # LIMIT/ICEBERG default to GTC; MARKET keeps its historical
    # immediate-or-cancel semantics. MARKET with explicit GTC and ICEBERG
    # with any other time-in-force are rejected during schema checks.
    tif: str = obj.get("time_in_force") or (
        GTC if order_type in (LIMIT, ICEBERG) else IOC
    )
    display_quantity: int | None = (
        obj["display_quantity"] if is_iceberg else None
    )
    account_id: str | None = obj.get("account_id")
    if account_id is not None:
        # Any accepted ADD makes its account known, regardless of how the
        # order itself ends up.
        self._accounts.add(account_id)

    # FOK must either match the whole quantity against the pre-event book
    # or do nothing at all: no trades, no book change, no trade ids spent.
    # The precheck walks the book in the same price-time order a real fill
    # would; a resting iceberg offers its full remaining quantity here,
    # including reserve that is not part of the visible book totals. A
    # same-account resting order reached before the quantity is met aborts
    # the event atomically, before any trade could occur.
    if tif == FOK:
        fok = self._fok_probe(side, limit, quantity, account_id)
        if fok is not None:
            record: dict[str, object] = {
                "side": side,
                "price": limit,
                "remaining": quantity,
                "status": CANCELLED,
            }
            if account_id is not None:
                record["account_id"] = account_id
            self._orders[order_id] = record
            if fok is False:
                return event_id, UNFILLED_CANCELLED, None, [], None
            stp = {
                "maker_order_id": fok,
                "taker_order_id": order_id,
                "cancelled_quantity": quantity,
            }
            return event_id, SELF_TRADE_PREVENTED, None, [], stp

    remaining, trades, stp_maker = self._match(
        event_id, order_id, side, limit, remaining, account_id
    )

    record = {"side": side, "price": limit}
    if account_id is not None:
        record["account_id"] = account_id
    stp: dict[str, object] | None = None
    if stp_maker is not None:
        # The whole leftover is cancelled; the blocking passive order is
        # neither traded nor displaced, and no later liquidity is sought.
        result = (
            PARTIALLY_FILLED_SELF_TRADE_PREVENTED if trades else SELF_TRADE_PREVENTED
        )
        record["remaining"] = remaining
        record["status"] = CANCELLED
        stp = {
            "maker_order_id": stp_maker,
            "taker_order_id": order_id,
            "cancelled_quantity": remaining,
        }
    elif remaining == 0:
        result = FILLED
        record["remaining"] = 0
        record["status"] = FILLED
    elif order_type in (LIMIT, ICEBERG) and tif == GTC:
        result = PARTIALLY_FILLED_RESTING if trades else RESTING
        record["remaining"] = remaining
        record["status"] = RESTING
        self._rest(
            order_id, side, limit, remaining,
            display_quantity if is_iceberg else None, record,
        )
    else:
        # IOC leftovers never enter the book; a successful FOK is always
        # fully filled by construction of the pre-event availability check.
        result = PARTIALLY_FILLED_CANCELLED if trades else UNFILLED_CANCELLED
        record["remaining"] = remaining
        record["status"] = CANCELLED

    self._orders[order_id] = record
    return event_id, result, None, trades, stp

def _fok_probe(
    self, side: str, limit: int | None, quantity: int, account_id: str | None
) -> str | bool | None:
    """Probe a FOK request against the pre-event book without mutating it.

    Returns ``None`` when the whole quantity can be filled, ``False`` when
    liquidity runs short, or the id of the first same-account resting order
    reached before the quantity could be met. The walk mirrors a real fill:
    price-time priority across and within levels, and an exhausted iceberg
    slice replenishes at the tail of its level (including the hidden
    reserve) before the level is drained. Queues and slice sizes are copied
    for the simulation so the live book stays untouched.
    """
    opposite, _totals = self._opposite(side)
    tradable = self._tradable_fn(side, limit)
    need = quantity
    prices = sorted(opposite, reverse=side == SELL)
    for price in prices:
        if not tradable(price):
            continue
        sim_remaining: dict[str, int] = {}
        sim_visible: dict[str, int] = {}
        queue: deque[str] = deque()
        for maker_id in opposite[price]:
            maker = self._orders[maker_id]
            sim_remaining[maker_id] = maker["remaining"]
            if maker.get("visible") is not None:
                sim_visible[maker_id] = maker["visible"]
            queue.append(maker_id)
        while queue and need > 0:
            maker_id = queue.popleft()
            maker = self._orders[maker_id]
            if account_id is not None and maker.get("account_id") == account_id:
                return maker_id
            if maker_id in sim_visible:
                available = sim_visible[maker_id]
            else:
                available = sim_remaining[maker_id]
            need -= available
            sim_remaining[maker_id] -= available

"""Single-document JSON entry point for ordered multi-symbol event replay.

The command reads exactly one UTF-8 JSON request document from standard
input and writes exactly one UTF-8 JSON response document to standard
output. It never opens files; snapshots and results only travel through the
caller-supplied document.
"""

from __future__ import annotations

import json
import sys

from .event_replay import (
    SnapshotError,
    canonical_json,
    replay_events,
)

_ERROR_IO = "ERROR_IO\n"
_INVALID_REQUEST = "INVALID_REQUEST"


def _write_error(stdout: object, stderr: object, code: str, message: str) -> int:
    try:
        stdout.buffer.write(
            canonical_json({"error": {"code": code, "message": message}}) + b"\n"
        )
        stdout.buffer.flush()
    except OSError:
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1
    return 2


def serve_events(
    stdin: object = sys.stdin,
    stdout: object = sys.stdout,
    stderr: object = sys.stderr,
) -> int:
    """Run one events request. Returns the process exit code."""
    try:
        raw = stdin.buffer.read()
        text = raw.decode("utf-8")
    except (OSError, UnicodeError):
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1

    try:
        request = json.loads(text)
    except json.JSONDecodeError:
        return _write_error(stdout, stderr, _INVALID_REQUEST, "request must be one JSON document")
    if (
        not isinstance(request, dict)
        or not isinstance(request.get("events"), list)
        or not set(request) <= {"events", "config", "snapshot", "snapshot_after"}
        or (
            "config" in request
            and not isinstance(request["config"], dict)
        )
        or (
            "snapshot" in request
            and request["snapshot"] is not None
            and not isinstance(request["snapshot"], dict)
        )
    ):
        return _write_error(
            stdout, stderr, _INVALID_REQUEST,
            'request must be an object with an "events" list and optional '
            '"config" and "snapshot" objects',
        )

    marker = request.get("snapshot_after", "last")
    if marker is not None and marker != "last":
        if not (
            isinstance(marker, dict)
            and isinstance(marker.get("symbol"), str)
