"""Scratch v2: live-session-guided deterministic stream generator."""
import copy
from collections import Counter

from order_book_engine import (
    replay_events, EventReplayer, export_snapshot, restore_replayer,
    canonical_json,
)
from order_book_engine.engine import EXECUTION_REPORT, IMPACT_REPORT

BUY, SELL = "BUY", "SELL"
LIMIT, MARKET, ICEBERG = "LIMIT", "MARKET", "ICEBERG"
IOC, FOK, GTC = "IOC", "FOK", "GTC"

CONFIG = {"price_limits": {"AAA": {"lower": 90, "upper": 120},
                           "BBB": {"lower": 60, "upper": 90}}}
CENTRAL = {"AAA": 100, "BBB": 75, "CCC": 50}
STATIC_BAND = {"AAA": (90, 120), "BBB": (60, 90), "CCC": None}
SYMBOLS = ["AAA", "BBB", "CCC"]


class Rng:
    def __init__(self, seed):
        self.s = seed & 0xffffffff
    def u32(self):
        self.s = (1103515245 * self.s + 12345) & 0x7fffffff
        return self.s
    def rint(self, lo, hi):
        return lo + self.u32() % (hi - lo + 1)
    def pick(self, seq):
        return seq[self.u32() % len(seq)]


class SGen:
    def __init__(self, gen, sym):
        self.g, self.sym = gen, sym
        self.seq = 0
        self.orders = {}      # oid -> dict(side, price, tif, ice, peak, account, qty0)
        self.fills = {}       # oid -> cumulative filled qty
        self.rem = {}         # oid -> live remaining model
        self.live = set()     # resting oids
        self.plans = {}       # pid -> meta
        self.items = []
        self.no = 0
        self.np = 0
        self.accounts = set()
        c0, c1 = STATIC_BAND[sym] if STATIC_BAND[sym] else (None, None)
        self.band = (c0, c1) if c0 else None
        self.c = CENTRAL[sym]
        self.first_eid = None

    def eid(self):
        return self.g.eid()

    def cur(self):
        return self.seq + 1

    def submit(self, ev, advance=True, label=None):
        res = self.g.session.submit([copy.deepcopy(ev)])[0]
        self.items.append(ev)
        if label:
            self.g.labels[label] = ev["event_id"]
        if advance:
            self.seq += 1
        self.absorb(ev, res)
        return res

    def absorb(self, ev, res):
        t = ev.get("type")
        if res.get("status") == "ACCEPTED":
            if t == "ADD":
                oid = ev["order_id"]
                if oid not in self.orders:
                    self.orders[oid] = dict(
                        side=ev["side"], price=ev.get("price"),
                        tif=ev.get("time_in_force") or (GTC if ev["order_type"] == LIMIT else IOC),
                        ice=ev["order_type"] == ICEBERG,
                        peak=ev.get("display_quantity"),
                        account=ev.get("account_id"), qty0=ev["quantity"])
                    self.fills.setdefault(oid, 0)
                    self.rem[oid] = ev["quantity"]
                if ev.get("account_id"):
                    self.accounts.add(ev["account_id"])
                if res["result"] in ("RESTING", "PARTIALLY_FILLED_RESTING"):
                    self.live.add(oid)
            elif t == "CANCEL" and res["result"] == "CANCELLED":
                self.live.discard(ev["order_id"])
            elif t == "REPLACE":
                oid = ev["order_id"]
                self.orders[oid]["price"] = ev["price"]
                if "display_quantity" in ev:
                    self.orders[oid]["ice"] = True
                    self.orders[oid]["peak"] = ev["display_quantity"]
                self.rem[oid] = ev["quantity"] - sum(
                    tr["quantity"] for tr in res["trades"]
                    if tr["taker_order_id"] == oid)
                if res["result"] in ("REPLACED", "PARTIALLY_FILLED_RESTING"):
                    self.live.add(oid)
                else:
                    self.live.discard(oid)
            elif t.endswith("_START"):
                pid = ev["plan_id"]
                self.plans[pid] = dict(
                    algo=t.split("_")[0], side=ev["side"],
                    otype=ev["order_type"], price=ev.get("price"),
                    account=ev.get("account_id"), total=ev["total_quantity"])
                if ev.get("account_id"):
                    self.accounts.add(ev["account_id"])
        # trades attribution
        for tr in res.get("trades", []):
            for role in ("maker_order_id", "taker_order_id"):
                oid = tr[role]
                self.fills[oid] = self.fills.get(oid, 0) + tr["quantity"]
                if oid in self.rem:
                    self.rem[oid] -= tr["quantity"]
            mid = tr["maker_order_id"]
            if mid in self.live and self.rem.get(mid, 1) <= 0:
                self.live.discard(mid)
        # plan child registrations (for account attribution)
        ep = res.get("execution_plan")
        if ep is not None and ep.get("child_order_id"):
            cid = ep["child_order_id"]
            pid = ev.get("plan_id")
            meta = self.plans.get(pid)
            if meta:
                self.orders.setdefault(cid, dict(
                    side=meta["side"], price=meta["price"], tif=IOC,
                    ice=False, peak=None, account=meta["account"],
                    qty0=ep.get("scheduled_quantity") or ep.get("released_quantity")))

    # envelope helpers
    def ev(self, payload, seq=None, eid_=None):
        e = {"event_id": eid_ or self.eid(), "symbol": self.sym,
             "sequence": self.cur() if seq is None else seq}
        e.update(payload)
        if self.first_eid is None and seq is None:
            self.first_eid = e["event_id"]
        return e

    def raw(self, ev, advance=False, label=None):
        return self.submit(ev, advance=advance, label=label)

    def ask_total(self, max_price=None):
        bids, asks = self.g.session.book(self.sym)
        return sum(q for p, q in ((a["price"], a["quantity"]) for a in asks)
                   if max_price is None or p <= max_price)

    def best_ask(self):
        _, asks = self.g.session.book(self.sym)
        return asks[0]["price"] if asks else None

    def in_band(self, p):
        return self.band is None or self.band[0] <= p <= self.band[1]

    def bp(self, around, dlo=0, dhi=0):
        for _ in range(60):
            p = around + self.g.rng.rint(dlo, dhi)
            if p > 0 and self.in_band(p):
                return p
        return around

    def new_oid(self):
        self.no += 1
        return f"{self.sym}.o{self.no}"

    def new_pid(self):
        self.np += 1
        return f"{self.sym}.P{self.np}"

    def add(self, side, otype, qty, price=None, tif=None, account=None,
            display=None, oid=None, seq=None, label=None, advance=True):
        p = {"type": "ADD", "order_id": oid or self.new_oid(), "side": side,
             "order_type": otype, "quantity": qty}
        if price is not None: p["price"] = price
        if tif is not None: p["time_in_force"] = tif
        if account is not None: p["account_id"] = account
        if display is not None: p["display_quantity"] = display
        return self.raw(self.ev(p, seq=seq), advance=advance, label=label)

    def cancel(self, oid, seq=None, label=None, advance=True, eid_=None):
        return self.raw(self.ev({"type": "CANCEL", "order_id": oid}, seq=seq, eid_=eid_),
                        advance=advance, label=label)

    def resting_sells_plain(self):
        return [o for o in self.live
                if self.orders[o]["side"] == SELL and not self.orders[o]["ice"]]


class Generator:
    def __init__(self, seed):
        self.rng = Rng(seed)
        self.seed = seed
        self.session = EventReplayer(copy.deepcopy(CONFIG))
        self.counter = 0
        self.labels = {}
        self.sgs = {s: SGen(self, s) for s in SYMBOLS}

    def eid(self):
        self.counter += 1
        return f"ev{self.counter:04d}"

    # ---- per-symbol script ------------------------------------------------
    def script(self, sg):
        r, c = self.rng, sg.c
        A = lambda n: f"{sg.sym}.{n}"

        # A. seed makers
        sg.add(SELL, LIMIT, r.rint(4, 6), sg.bp(c, 0, 1), account=A("alpha"), label="first")
        sg.add(BUY, LIMIT, r.rint(2, 4), sg.bp(c, -3, -2), account=A("beta"))
        sg.add(SELL, ICEBERG, r.rint(10, 14), sg.bp(c, 0, 0),
               account=A("ice"), display=r.rint(2, 3))
        sg.add(SELL, LIMIT, r.rint(1, 2), sg.bp(c, 0, 1))

        # B. takers
        sg.add(BUY, MARKET, 1, account=A("taker"), label="market_partial")
        sg.add(BUY, LIMIT, r.rint(1, 2), sg.bp(c, 2, 3), tif=IOC)
        liq = sg.ask_total()
        if liq < 1:
            sg.add(SELL, LIMIT, 3, sg.bp(c, 0, 1), account=A("liq"))
            liq = sg.ask_total()
        sg.add(BUY, MARKET, liq, tif=FOK, label="fok_fill")
        sg.add(BUY, MARKET, 999, tif=FOK, label="fok_fail")
        stp_p = sg.bp(c, -1, -1)
        sg.add(SELL, LIMIT, 2, stp_p, account=A("stp"))
        sg.add(BUY, MARKET, 2, account=A("stp"), label="stp")

        # C. cancels
        cand = sg.resting_sells_plain()
        if cand:
            target = r.pick(cand)
            sg.cancel(target, label="cancel_ok")
        sg.cancel(A("ghost"), label="cancel_unknown")

        # D. replaces
        cand = sg.resting_sells_plain()
        if cand:
            target = r.pick(cand)
            price = sg.orders[target]["price"]
            self._plain_event(sg, "REPLACE", order_id=target,
                              quantity=r.rint(1, 5), price=price, label="replace_ok")
        self._plain_event(sg, "REPLACE", order_id=A("ghost"), quantity=1, price=c,
                          label="replace_unknown")
        cand = sg.resting_sells_plain()
        if cand:
            target = r.pick(cand)
            price = sg.orders[target]["price"]
            self._plain_event(sg, "REPLACE", order_id=target,
                              quantity=r.rint(1, 5), price=price,
                              display_quantity=1, label="replace_plain_display")
        # duplicate order id
        dup = next(iter(sg.orders))
        meta = sg.orders[dup]
        if meta["otype_tif"]:  # placeholder
            pass

    def _plain_event(self, sg, ttype, label=None, advance=True, seq=None, **fields):
        p = {"type": ttype}; p.update(fields)
        return sg.raw(sg.ev(p, seq=seq), advance=advance, label=label)

